content.content:
        "uniprot_id": entry.get("primaryAccession", ""),
        "protein_name": entry.get("proteinDescription", {}).get("recommendedName", {}).get("fullName", {}).get("value", ""),
        "length": entry.get("sequence", {}).get("length", 0),
        "mass": entry.get("sequence", {}).get("mass", 0),
        "subcellular_locations": [],
        "domains": [],
        "ptms": [],
        "function": "",
        "tissue_specificity": "",
        "disease_involvement": [],
        "trafficking_note": "",
        "keywords": []
    }

    # Extract subcellular locations
    if "comments" in entry:
        for comment in entry["comments"]:
            if comment.get("commentType") == "SUBCELLULAR LOCATION":
                for location in comment.get("subcellularLocations", []):
                    loc_text = location.get("location", {}).get("value", "")
                    if loc_text:
                        protein_info["subcellular_locations"].append(loc_text)
                # Extract trafficking/internalization note from the comment
                note_text = comment.get("note", {}).get("texts", [{}])
                if note_text:
                    note_val = note_text[0].get("value", "") if isinstance(note_text, list) else ""
                    if note_val:
                        protein_info["trafficking_note"] = note_val

            elif comment.get("commentType") == "FUNCTION":
                protein_info["function"] = comment.get("texts", [{}])[0].get("value", "")

            elif comment.get("commentType") == "TISSUE SPECIFICITY":
                protein_info["tissue_specificity"] = comment.get("texts", [{}])[0].get("value", "")

            elif comment.get("commentType") == "DISEASE":
                disease_text = comment.get("disease", {}).get("diseaseId", "")
                if disease_text:
                    protein_info["disease_involvement"].append(disease_text)

    # Extract features (domains, PTMs)
    if "features" in entry:
        for feature in entry["features"]:
            feature_type = feature.get("type", "")
            description = feature.get("description", "")

            if feature_type in ["Domain", "Repeat", "Region"]:
                if description:
                    protein_info["domains"].append({
                        "type": feature_type,
                        "description": description,
                        "start": feature.get("location", {}).get("start", {}).get("value", 0),
                        "end": feature.get("location", {}).get("end", {}).get("value", 0)
                    })

            elif feature_type in ["Modified residue", "Glycosylation", "Disulfide bond"]:
                if description:
                    protein_info["ptms"].append({
                        "type": feature_type,
                        "description": description,
                        "position": feature.get("location", {}).get("start", {}).get("value", 0)
                    })

    # Extract trafficking-relevant keywords
    trafficking_keywords = {
        "Endocytosis", "Receptor-mediated endocytosis", "Clathrin-mediated endocytosis",
        "Endosome", "Lysosome", "Cell membrane", "Membrane protein",
    }
    for kw in entry.get("keywords", []):
        kw_name = kw.get("name", "")
        if kw_name in trafficking_keywords:
            protein_info["keywords"].append(kw_name)

    return protein_info

except Exception as e:
